import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import { 
  ArrowPathIcon, 
  PlusIcon, 
  PencilIcon, 
  TrashIcon,
  XMarkIcon
} from '@heroicons/react/24/outline';
import phoneService from '../../services/phoneService';

const PhoneManagement = () => {
  const [phones, setPhones] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentPhone, setCurrentPhone] = useState({
    title: '',
    brand: '',
    model: '',
    price: '',
    originalPrice: '',
    storage: '',
    color: '',
    condition: '良好',
    description: '',
    images: []
  });
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedImages, setSelectedImages] = useState([]);
  const [imagePreview, setImagePreview] = useState([]);

  // 获取所有手机
  useEffect(() => {
    fetchPhones();
  }, []);

  const fetchPhones = async () => {
    try {
      setLoading(true);
      const data = await phoneService.getPhones();
      setPhones(data);
    } catch (error) {
      console.error('获取手机列表失败:', error);
      toast.error('获取手机列表失败');
    } finally {
      setLoading(false);
    }
  };

  // 处理表单输入变化
  const handleChange = (e) => {
    const { name, value } = e.target;
    setCurrentPhone({ ...currentPhone, [name]: value });
  };

  // 处理图片上传
  const handleImageChange = (e) => {
    if (e.target.files) {
      const filesArray = Array.from(e.target.files);
      
      // 创建预览URL
      const newPreviewImages = filesArray.map(file => URL.createObjectURL(file));
      setImagePreview([...imagePreview, ...newPreviewImages]);
      setSelectedImages([...selectedImages, ...filesArray]);
    }
  };

  // 移除图片
  const removeImage = (index) => {
    // 释放预览URL
    URL.revokeObjectURL(imagePreview[index]);
    
    // 更新状态
    setImagePreview(imagePreview.filter((_, i) => i !== index));
    setSelectedImages(selectedImages.filter((_, i) => i !== index));
  };

  // 打开添加手机模态框
  const openAddModal = () => {
    setCurrentPhone({
      title: '',
      brand: '',
      model: '',
      price: '',
      originalPrice: '',
      storage: '',
      color: '',
      condition: '良好',
      description: '',
      images: []
    });
    setImagePreview([]);
    setSelectedImages([]);
    setIsEditing(false);
    setShowModal(true);
  };

  // 打开编辑手机模态框
  const openEditModal = (phone) => {
    setCurrentPhone({
      _id: phone._id,
      title: phone.title,
      brand: phone.brand,
      model: phone.model,
      price: phone.price,
      originalPrice: phone.originalPrice || '',
      storage: phone.storage,
      color: phone.color,
      condition: phone.condition,
      description: phone.description,
      images: phone.images
    });
    setImagePreview(phone.images || []);
    setSelectedImages([]);
    setIsEditing(true);
    setShowModal(true);
  };

  // 提交表单
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    try {
      // 验证必填字段
      if (!currentPhone.title || !currentPhone.brand || !currentPhone.model || 
          !currentPhone.price || !currentPhone.storage || !currentPhone.color || 
          !currentPhone.description) {
        toast.error('请填写所有必填字段');
        return;
      }
      
      // 验证价格是数字
      if (isNaN(currentPhone.price) || (currentPhone.originalPrice && isNaN(currentPhone.originalPrice))) {
        toast.error('价格必须是数字');
        return;
      }
      
      // 验证图片
      if (!isEditing && selectedImages.length === 0) {
        toast.error('请至少上传一张图片');
        return;
      }
      
      // 创建FormData对象
      const formData = new FormData();
      formData.append('title', currentPhone.title);
      formData.append('brand', currentPhone.brand);
      formData.append('model', currentPhone.model);
      formData.append('price', currentPhone.price);
      if (currentPhone.originalPrice) {
        formData.append('originalPrice', currentPhone.originalPrice);
      }
      formData.append('storage', currentPhone.storage);
      formData.append('color', currentPhone.color);
      formData.append('condition', currentPhone.condition);
      formData.append('description', currentPhone.description);
      
      // 添加已有图片
      if (isEditing && currentPhone.images) {
        currentPhone.images.forEach(image => {
          formData.append('existingImages', image);
        });
      }
      
      // 添加新图片
      selectedImages.forEach(file => {
        formData.append('images', file);
      });
      
      if (isEditing) {
        await phoneService.updatePhone(currentPhone._id, formData);
        toast.success('手机信息已更新');
      } else {
        await phoneService.createPhone(formData);
        toast.success('手机信息已添加');
      }
      
      setShowModal(false);
      fetchPhones();
    } catch (error) {
      console.error('保存手机信息失败:', error);
      toast.error('保存失败，请稍后再试');
    }
  };

  // 删除手机
  const handleDelete = async (id) => {
    if (window.confirm('确定要删除这个手机商品吗？')) {
      try {
        await phoneService.deletePhone(id);
        toast.success('手机商品已删除');
        fetchPhones();
      } catch (error) {
        console.error('删除手机失败:', error);
        toast.error('删除失败，请稍后再试');
      }
    }
  };

  // 过滤手机
  const filteredPhones = phones.filter(
    (phone) =>
      phone.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      phone.brand.toLowerCase().includes(searchTerm.toLowerCase()) ||
      phone.model.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <ArrowPathIcon className="animate-spin h-8 w-8 text-primary-600" />
        <span className="ml-2 text-gray-600">加载中...</span>
      </div>
    );
  }

  return (
    <div>
      <div className="mb-6">
        <h2 className="text-lg font-medium text-gray-900">手机管理</h2>
        <p className="mt-1 text-sm text-gray-500">
          添加、编辑和管理手机商品信息
        </p>
      </div>

      {/* 搜索和添加按钮 */}
      <div className="mb-6 flex flex-col sm:flex-row justify-between gap-4">
        <div className="sm:w-2/3">
          <div className="relative rounded-md shadow-sm">
            <input
              type="text"
              className="input pr-10"
              placeholder="搜索手机标题、品牌或型号..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
              <svg
                className="h-5 w-5 text-gray-400"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
                ></path>
              </svg>
            </div>
          </div>
        </div>
        <div>
          <button
            onClick={openAddModal}
            className="w-full sm:w-auto flex items-center justify-center px-4 py-2 border border-transparent text-sm font-medium rounded-md text-white bg-primary-600 hover:bg-primary-700"
          >
            <PlusIcon className="h-5 w-5 mr-2" />
            添加手机
          </button>
        </div>
      </div>

      {/* 手机列表 */}
      <div className="bg-white shadow overflow-hidden sm:rounded-md">
        <ul className="divide-y divide-gray-200">
          {filteredPhones.length === 0 ? (
            <li className="px-6 py-4 text-center text-gray-500">
              没有找到匹配的手机商品
            </li>
          ) : (
            filteredPhones.map((phone) => (
              <li key={phone._id} className="px-6 py-4">
                <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center">
                  <div className="flex items-center mb-4 sm:mb-0">
                    <div className="w-16 h-16 bg-gray-200 rounded overflow-hidden">
                      {phone.images && phone.images[0] && (
                        <img
                          src={phone.images[0]}
                          alt={phone.title}
                          className="w-full h-full object-cover"
                        />
                      )}
                    </div>
                    <div className="ml-4">
                      <div className="text-sm font-medium text-gray-900">
                        {phone.title}
                      </div>
                      <div className="text-sm text-gray-500">
                        {phone.brand} {phone.model} · {phone.storage} · {phone.color}
                      </div>
                      <div className="text-sm font-bold text-primary-600">
                        ¥{phone.price}
                        {phone.originalPrice && (
                          <span className="text-xs text-gray-500 line-through ml-2">
                            ¥{phone.originalPrice}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="flex space-x-2">
                    <button
                      onClick={() => openEditModal(phone)}
                      className="px-3 py-1 text-xs text-white bg-blue-600 rounded hover:bg-blue-700"
                    >
                      <PencilIcon className="h-4 w-4" />
                    </button>
                    <button
                      onClick={() => handleDelete(phone._id)}
                      className="px-3 py-1 text-xs text-white bg-red-600 rounded hover:bg-red-700"
                    >
                      <TrashIcon className="h-4 w-4" />
                    </button>
                  </div>
                </div>
              </li>
            ))
          )}
        </ul>
      </div>

      {/* 添加/编辑手机模态框 */}
      {showModal && (
        <div className="fixed inset-0 z-50 overflow-y-auto">
          <div className="flex items-center justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
            <div className="fixed inset-0 transition-opacity" aria-hidden="true">
              <div className="absolute inset-0 bg-gray-500 opacity-75"></div>
            </div>

            <div className="inline-block align-bottom bg-white rounded-lg text-left overflow-hidden shadow-xl transform transition-all sm:my-8 sm:align-middle sm:max-w-lg sm:w-full">
              <div className="bg-white px-4 pt-5 pb-4 sm:p-6 sm:pb-4">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-medium text-gray-900">
                    {isEditing ? '编辑手机信息' : '添加新手机'}
                  </h3>
                  <button
                    onClick={() => setShowModal(false)}
                    className="text-gray-400 hover:text-gray-500"
                  >
                    <XMarkIcon className="h-6 w-6" />
                  </button>
                </div>
                <form onSubmit={handleSubmit}>
                  <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                    <div className="sm:col-span-2">
                      <label className="block text-sm font-medium text-gray-700">
                        标题 <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="text"
                        name="title"
                        className="input mt-1"
                        value={currentPhone.title}
                        onChange={handleChange}
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        品牌 <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="text"
                        name="brand"
                        className="input mt-1"
                        value={currentPhone.brand}
                        onChange={handleChange}
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        型号 <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="text"
                        name="model"
                        className="input mt-1"
                        value={currentPhone.model}
                        onChange={handleChange}
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        价格 (¥) <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="number"
                        name="price"
                        className="input mt-1"
                        value={currentPhone.price}
                        onChange={handleChange}
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        原价 (¥)
                      </label>
                      <input
                        type="number"
                        name="originalPrice"
                        className="input mt-1"
                        value={currentPhone.originalPrice}
                        onChange={handleChange}
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        存储容量 <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="text"
                        name="storage"
                        className="input mt-1"
                        value={currentPhone.storage}
                        onChange={handleChange}
                        placeholder="如: 128GB"
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        颜色 <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="text"
                        name="color"
                        className="input mt-1"
                        value={currentPhone.color}
                        onChange={handleChange}
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        成色 <span className="text-red-500">*</span>
                      </label>
                      <select
                        name="condition"
                        className="input mt-1"
                        value={currentPhone.condition}
                        onChange={handleChange}
                        required
                      >
                        <option value="全新">全新</option>
                        <option value="几乎全新">几乎全新</option>
                        <option value="良好">良好</option>
                        <option value="一般">一般</option>
                      </select>
                    </div>
                    <div className="sm:col-span-2">
                      <label className="block text-sm font-medium text-gray-700">
                        描述 <span className="text-red-500">*</span>
                      </label>
                      <textarea
                        name="description"
                        rows="3"
                        className="input mt-1"
                        value={currentPhone.description}
                        onChange={handleChange}
                        required
                      ></textarea>
                    </div>
                    <div className="sm:col-span-2">
                      <label className="block text-sm font-medium text-gray-700">
                        图片 <span className="text-red-500">*</span>
                      </label>
                      
                      {/* 图片预览 */}
                      {imagePreview.length > 0 && (
                        <div className="grid grid-cols-3 gap-2 mt-2 mb-3">
                          {imagePreview.map((src, index) => (
                            <div key={index} className="relative">
                              <img
                                src={src}
                                alt={`手机图片 ${index + 1}`}
                                className="w-full h-24 object-cover rounded"
                              />
                              {(!isEditing || index >= (currentPhone.images?.length || 0)) && (
                                <button
                                  type="button"
                                  onClick={() => removeImage(index)}
                                  className="absolute -top-2 -right-2 bg-white rounded-full p-1 shadow"
                                >
                                  <XMarkIcon className="h-4 w-4 text-red-500" />
                                </button>
                              )}
                            </div>
                          ))}
                        </div>
                      )}
                      
                      {/* 上传按钮 */}
                      <div className="mt-2">
                        <label className="block w-full border-2 border-dashed border-gray-300 rounded-md p-4 text-center cursor-pointer hover:border-primary-500">
                          <svg
                            className="mx-auto h-12 w-12 text-gray-400"
                            stroke="currentColor"
                            fill="none"
                            viewBox="0 0 48 48"
                            aria-hidden="true"
                          >
                            <path
                              d="M28 8H12a4 4 0 00-4 4v20m32-12v8m0 0v8a4 4 0 01-4 4H12a4 4 0 01-4-4v-4m32-4l-3.172-3.172a4 4 0 00-5.656 0L28 28M8 32l9.172-9.172a4 4 0 015.656 0L28 28m0 0l4 4m4-24h8m-4-4v8m-12 4h.02"
                              strokeWidth="2"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            />
                          </svg>
                          <span className="mt-2 block text-sm text-gray-500">
                            点击上传图片
                          </span>
                          <input
                            type="file"
                            className="hidden"
                            accept="image/*"
                            multiple
                            onChange={handleImageChange}
                          />
                        </label>
                      </div>
                    </div>
                  </div>
                  <div className="mt-5 sm:mt-6 sm:grid sm:grid-cols-2 sm:gap-3">
                    <button
                      type="button"
                      className="w-full inline-flex justify-center rounded-md border border-gray-300 shadow-sm px-4 py-2 bg-white text-base font-medium text-gray-700 hover:bg-gray-50 focus:outline-none sm:text-sm"
                      onClick={() => setShowModal(false)}
                    >
                      取消
                    </button>
                    <button
                      type="submit"
                      className="w-full inline-flex justify-center rounded-md border border-transparent shadow-sm px-4 py-2 bg-primary-600 text-base font-medium text-white hover:bg-primary-700 focus:outline-none sm:text-sm"
                    >
                      {isEditing ? '更新' : '添加'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PhoneManagement;
